-- ----------------------------
-- Table structure for bill
-- ----------------------------
DROP TABLE IF EXISTS `bill`;
CREATE TABLE `bill`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `bill_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '账单编号',
  `bill_type` tinyint NOT NULL DEFAULT 0 COMMENT '账单类型 0月度账单 1费用账单',
  `elder_id` bigint NOT NULL COMMENT '老人ID（elder.id）',
  `check_in_config_id` bigint NULL DEFAULT NULL COMMENT '入住配置ID（check_in_config.id）',
  `family_member_id` bigint NULL DEFAULT NULL COMMENT '小程序用户ID（family_member.id）',
  `bill_month` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '账单月份（yyyy-MM）',
  `bill_start_time` datetime NULL DEFAULT NULL COMMENT '账单开始时间',
  `bill_end_time` datetime NULL DEFAULT NULL COMMENT '账单结束时间',
  `total_days` int NULL DEFAULT NULL COMMENT '账单天数',
  `lname` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '护理等级名称',
  `type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '房型名称',
  `bed_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '床位费',
  `nursing_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '护理费',
  `other_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '其他费用',
  `medical_insurance_payment` decimal(10, 2) NULL DEFAULT NULL COMMENT '医保支付',
  `government_subsidy` decimal(10, 2) NULL DEFAULT NULL COMMENT '政府补贴',
  `month_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '每月应付',
  `current_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '本期应付',
  `deposit_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '押金',
  `bill_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '账单金额',
  `prepaid_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '预缴款支付',
  `payable_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '应付金额',
  `transaction_status` tinyint NOT NULL DEFAULT 0 COMMENT '支付状态 0待支付 1已支付 2已关闭',
  `payment_deadline` datetime NULL DEFAULT NULL COMMENT '支付截止时间',
  `transaction_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_elder_bill_start`(`elder_id` ASC, `bill_start_time` ASC) USING BTREE,
  INDEX `idx_member_status`(`family_member_id` ASC, `transaction_status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '费用账单表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of bill
-- ----------------------------

-- ----------------------------
-- Table structure for check_in
-- ----------------------------
DROP TABLE IF EXISTS `check_in`;
CREATE TABLE `check_in`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `elder_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '老人姓名',
  `elder_id` bigint NOT NULL COMMENT '老人ID',
  `id_card_no` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '身份证号',
  `start_date` date NOT NULL COMMENT '入住开始时间',
  `end_date` date NULL DEFAULT NULL COMMENT '入住结束时间',
  `nursing_level_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '护理等级名称',
  `bed_number` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '入住床位',
  `status` tinyint NOT NULL DEFAULT 0 COMMENT '状态 (0: 已入住, 1: 已退住)',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序编号',
  `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT NULL COMMENT '修改时间',
  `create_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_by` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

