INSERT INTO `health_assessment_data_collection` VALUES (6, '{\"elderName\":\"王德法\",\"idCard\":\"360721200609040219\",\"birthDate\":\"2006-09-04\",\"age\":20,\"gender\":\"男\",\"nation\":\"汉族\",\"socialSecurityCard\":\"24454354\",\"religiousBelief\":\"无\",\"educationLevel\":\"高中/技校/中专\",\"maritalStatus\":\"已婚\",\"livingSituation\":\"独居\",\"medicalPaymentMethod\":\"城镇职工基本医疗保险\",\"economicSource\":\"退休金/养老金\",\"elderContact\":\"13452156258\",\"providerName\":\"王德可\",\"providerContact\":\"13524785262\",\"relationshipWithElder\":\"子女\",\"informedConsentUrl\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/7e428533-4db3-4755-9a2e-fb99a06fc22e.pdf\"}', '{\"diseaseDiagnosis\":{\"dementia\":\"无\",\"mentalIllness\":\"无\",\"chronicDiseases\":\"香港脚\"},\"recent30Days\":{\"fall\":0,\"lost\":0,\"choking\":0,\"suicideAttempt\":0,\"coma\":0,\"medicalReport\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/7746970f-36f3-4d79-9d1d-d70a6bbef3f2.pdf\"}}', '{\"eating\":\"可独立进食（在合理的时间内独立进食准备好的食物）\",\"bathing\":\"准备好洗澡水后，可自己独立完成洗澡过程\",\"grooming\":\"可自己独立完成\",\"dressing\":\"可独立完成\",\"bowelControl\":\"可控制大便\",\"bladderControl\":\"可控制小便\",\"toileting\":\"可独立完成\",\"chairTransfer\":\"可独立完成\",\"walkingOnFlatGround\":\"可独立在平地上行走45m\",\"upDownStairs\":\"可独立上下楼梯（连续上下10-15个台阶）\",\"totalScore\":100,\"abilityRating\":\"能力完好\"}', '{\"recallWords\":\"苹果、手表、国旗\",\"clockDrawingTest\":{\"url\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/cc96b3a7-32af-4606-98eb-18b7e5fa3e2a.png\",\"result\":0},\"aggressiveBehavior\":\"无身体攻击行为（如打/踢/推/咬/抓/摔东西）和语言攻击行为（如骂人、语言威胁、尖叫）\",\"depressiveSymptoms\":\"无\",\"totalScore\":0,\"abilityRating\":\"能力完好\"}', '{\"consciousLevel\":\"神志清醒，对周围环境警觉\",\"vision\":\"能看清楚大字体，但看不清书报上的标准字体\",\"hearing\":\"可正常交谈，能听到电视、电话、门铃的声音\",\"communication\":\"无困难，能与他人正常沟通和交流\",\"abilityRating\":\"能力完好\"}', '{\"livingAbility\":\"除个人生活自理外（如饮食、洗漱、穿戴、二便），能料理家务（如做饭、洗衣）或当家管理事务\",\"workAbility\":\"原来熟练的脑力工作或体力技巧性工作可照常进行\",\"timeSpaceOrientation\":\"时间观念（年、月、日、时）清楚；可单独出远门，能很快掌握新环境的方位\",\"personOrientation\":\"知道周围人们的关系，知道祖孙、叔伯、姑姨、侄子侄女等称谓的意义；可分辨陌生人的大致年龄和身份，可用适当称呼\",\"socialSkills\":\"参与社会，在社会环境有一定的适应能力，待人接物恰当\",\"totalScore\":0,\"abilityRating\":\"能力完好\"}', NULL, '2026-10-08 14:42:44', '2026-10-08 20:34:31', 1, 1, NULL);
INSERT INTO `health_assessment_data_collection` VALUES (8, '{\"elderName\":\"我不是的\",\"idCard\":\"360721200309204521\",\"birthDate\":\"2003-09-20\",\"age\":23,\"gender\":\"女\",\"nation\":\"汉族\",\"socialSecurityCard\":\"1111111111\",\"religiousBelief\":\"无\",\"educationLevel\":\"文盲\",\"maritalStatus\":\"未婚\",\"livingSituation\":\"独居\",\"medicalPaymentMethod\":\"城镇居民基本医疗保险\",\"economicSource\":\"退休金/养老金\",\"elderContact\":\"13045254123\",\"providerName\":\"111\",\"providerContact\":\"13045254123\",\"relationshipWithElder\":\"配偶\",\"informedConsentUrl\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/7ab9e64a-ac76-4bc4-ad23-643bbe4a41f8.png\"}', '{\"diseaseDiagnosis\":{\"dementia\":\"无\",\"mentalIllness\":\"无\",\"chronicDiseases\":\"111111111\"},\"recent30Days\":{\"fall\":0,\"lost\":0,\"choking\":0,\"suicideAttempt\":0,\"coma\":0,\"medicalReport\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/4a32cf7b-e7e6-4291-9abe-c6905cbf9e1a.pdf\"}}', '{\"eating\":\"需极大帮助或完全依赖他人，或有留置营养管\",\"bathing\":\"准备好洗澡水后，可自己独立完成洗澡过程\",\"grooming\":\"可自己独立完成\",\"dressing\":\"可独立完成\",\"bowelControl\":\"可控制大便\",\"bladderControl\":\"可控制小便\",\"toileting\":\"可独立完成\",\"chairTransfer\":\"需部分帮助（需他人搀扶或使用拐杖）\",\"walkingOnFlatGround\":\"需部分帮助（因肢体残疾、平衡能力差、过度衰弱、视力等问题，在一定程度上需他人地搀扶或使用拐杖、助行器等辅助用具）\",\"upDownStairs\":\"需部分帮助（需他人搀扶，或扶着楼梯、使用拐杖等）\",\"totalScore\":75,\"abilityRating\":\"轻度受损\"}', '{\"recallWords\":\"1、1、1\",\"clockDrawingTest\":{\"url\":\"https://lining-qk.oss-cn-hangzhou.aliyuncs.com/2ed7d045-4722-41b1-b88f-bbc8295417ba.png\",\"result\":0},\"aggressiveBehavior\":\"无身体攻击行为（如打/踢/推/咬/抓/摔东西）和语言攻击行为（如骂人、语言威胁、尖叫）\",\"depressiveSymptoms\":\"情绪低落、不爱说话、不爱梳洗、不爱活动\",\"totalScore\":1,\"abilityRating\":\"轻度受损\"}', '{\"consciousLevel\":\"嗜睡，表现为睡眠状态过度延长。当呼唤或推动其肢体时可唤醒，并进行正确的交谈或执行指令，停止刺激后又继续入睡\",\"vision\":\"辨认物体有困难，但眼睛能跟随物体移动，只能看到光、颜色和形状\",\"hearing\":\"可正常交谈，能听到电视、电话、门铃的声音\",\"communication\":\"无困难，能与他人正常沟通和交流\",\"abilityRating\":\"中度受损\"}', '{\"livingAbility\":\"除个人生活自理外（如饮食、洗漱、穿戴、二便），能料理家务（如做饭、洗衣）或当家管理事务\",\"workAbility\":\"原来熟练的脑力工作或体力技巧性工作可照常进行\",\"timeSpaceOrientation\":\"时间观念有些下降，年、月、日清楚，但有时相差几天；可单独来往于近街，知道现住地的名称和方位，但不知回家路线\",\"personOrientation\":\"知道周围人们的关系，知道祖孙、叔伯、姑姨、侄子侄女等称谓的意义；可分辨陌生人的大致年龄和身份，可用适当称呼\",\"socialSkills\":\"参与社会，在社会环境有一定的适应能力，待人接物恰当\",\"totalScore\":1,\"abilityRating\":\"能力完好\"}', NULL, '2026-10-08 21:16:06', '2026-10-08 21:17:13', 1, 1, NULL);
INSERT INTO `health_assessment_report` VALUES (1, 6, '2026-10-08 20:35:58', 'admin', NULL, NULL, NULL, NULL, '能力完好', '能力完好', '能力完好', '能力完好', '能力完好', '能力完好', '', NULL, NULL, NULL, NULL, '75.0', '风险', '体检报告中心率偏快、偶发早搏、皮肤循环不良、视力下降、听力下降、口腔牙周炎、脂肪肝、慢性胆囊炎、脾轻度增大、右肾囊肿、前列腺增大等多项指标提示异常，血糖、血脂等处于临界水平；血常规、尿常规、免疫、胸片等未见明显异常。综合临床指标和数据分析：循环系统、消化系统、泌尿系统存在隐患，其中循环系统有“中危”风险，需重点关注心脏及血管功能；消化系统有“低危”风险，需进一步检查肝胆；泌尿系统有“低危”风险，定期监测肾囊肿及前列腺。建议保持健康生活方式，低脂低糖饮食，适当运动，戒烟限酒，并针对上述异常进行专项检查与随访。', '[{\"conclusion\":\"心率偏快\",\"examinationItem\":\"心率（内科）\",\"result\":\"92次/分\",\"referenceValue\":\"60-100次/分\",\"unit\":\"次/分\",\"interpret\":\"静息心率正常范围60-100次/分，92次/分处于正常上限，结合年龄及偶发早搏，可能提示自主神经功能调节异常或心脏负荷增加。\",\"advice\":\"建议行动态心电图检查，注意休息，避免浓茶、咖啡，监测血压和心率变化。\"},{\"conclusion\":\"偶发早搏\",\"examinationItem\":\"心律（内科）\",\"result\":\"偶发早搏\",\"referenceValue\":\"齐\",\"unit\":\"-\",\"interpret\":\"早搏是常见心律失常，偶发可见于正常人，也可因心肌缺血、电解质紊乱、精神紧张等引起。\",\"advice\":\"建议进一步行动态心电图、心肌酶、电解质检查，必要时心内科就诊。\"},{\"conclusion\":\"皮肤弹性差，四肢末梢凉\",\"examinationItem\":\"其他（内科）\",\"result\":\"皮肤弹性差，四肢末梢凉\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"提示可能存在周围循环障碍或末梢灌注不足，常见于动脉硬化、微循环功能下降等。\",\"advice\":\"建议进行血管功能评估，注意保暖，适当运动，控制血脂血糖，避免长时间静坐。\"},{\"conclusion\":\"视力下降\",\"examinationItem\":\"视力（眼科）\",\"result\":\"左0.3，右0.4\",\"referenceValue\":\"≥1.0（成人正常视力）\",\"unit\":\"-\",\"interpret\":\"视力下降符合老视特征，但需排除白内障、眼底病变等器质性疾病。\",\"advice\":\"建议眼科全面检查，包括裂隙灯、眼底检查，配戴合适老花镜，定期复查视力。\"},{\"conclusion\":\"角膜老年环\",\"examinationItem\":\"角膜（眼科）\",\"result\":\"轻度老年环\",\"referenceValue\":\"无\",\"unit\":\"-\",\"interpret\":\"角膜老年环是脂质在角膜周边的沉积，老年人常见，可能与血脂异常相关。\",\"advice\":\"建议检查血脂水平，如存在高脂血症应进行相应干预。\"},{\"conclusion\":\"结膜充血\",\"examinationItem\":\"结膜（眼科）\",\"result\":\"轻微充血\",\"referenceValue\":\"无充血\",\"unit\":\"-\",\"interpret\":\"结膜充血可能与结膜炎、用眼过度、环境刺激等因素有关。\",\"advice\":\"注意用眼卫生，避免长时间用眼，必要时使用抗炎眼药水，避免揉眼。\"},{\"conclusion\":\"左耳听力下降\",\"examinationItem\":\"听力（耳鼻喉科）\",\"result\":\"左耳轻度下降，右耳正常\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"左侧轻度听力下降可能为老年性耳聋、噪声损伤或中耳疾病所致。\",\"advice\":\"建议耳鼻喉科进一步行纯音测听及声导抗检查，避免噪声刺激，必要时佩戴助听器。\"},{\"conclusion\":\"鼻中隔弯曲\",\"examinationItem\":\"鼻中隔（耳鼻喉科）\",\"result\":\"轻度弯曲\",\"referenceValue\":\"居中\",\"unit\":\"-\",\"interpret\":\"轻度鼻中隔弯曲多无明显症状，部分可影响鼻通气。\",\"advice\":\"如无明显症状无需特殊处理；如有鼻塞、头痛等可就诊耳鼻喉科。\"},{\"conclusion\":\"口咽部充血\",\"examinationItem\":\"口咽部（耳鼻喉科）\",\"result\":\"轻微充血\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"口咽部充血提示咽部存在轻度炎症，可能为上呼吸道感染或慢性咽炎。\",\"advice\":\"建议多饮水，清淡饮食，忌辛辣刺激，注意休息；如有疼痛、发热需就医。\"},{\"conclusion\":\"口腔黏膜炎症\",\"examinationItem\":\"口腔粘膜（口腔科）\",\"result\":\"轻微炎症\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"口腔黏膜炎症可能与口腔卫生不良、义齿刺激、维生素缺乏、免疫力下降等有关。\",\"advice\":\"保持口腔清洁，补充B族维生素，避免刺激性食物，定期口腔检查。\"},{\"conclusion\":\"牙周炎\",\"examinationItem\":\"牙周（口腔科）\",\"result\":\"牙周炎，牙龈退缩\",\"referenceValue\":\"正常\",\"unit\":\"-\",\"interpret\":\"牙周炎是细菌感染引起的慢性炎症，可导致牙龈退缩、牙齿松动脱落，并与心血管疾病相关。\",\"advice\":\"建议进行牙周系统治疗（如洁治、刮治），掌握正确刷牙方法，使用牙线，定期复查。\"},{\"conclusion\":\"牙齿部分缺失\",\"examinationItem\":\"牙齿（口腔科）\",\"result\":\"部分缺失，余牙石较多\",\"referenceValue\":\"牙列完整\",\"unit\":\"-\",\"interpret\":\"牙齿缺失影响咀嚼功能，余牙代偿性负荷增加，牙石多进一步加重牙周炎。\",\"advice\":\"建议及时修复缺失牙，进行全口洁治（洗牙），防治牙周病。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙，考虑轻度脂肪肝可能\",\"referenceValue\":\"肝脏形态大小正常，实质回声均匀\",\"unit\":\"-\",\"interpret\":\"脂肪肝指肝细胞内脂肪堆积，与高脂饮食、饮酒、肥胖、糖尿病等密切相关，长期可致肝功能受损。\",\"advice\":\"建议低脂低糖饮食，增加有氧运动，控制体重，戒酒，复查肝功能及肝脏B超。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙，胆管未见扩张\",\"referenceValue\":\"胆囊壁光滑，胆囊大小正常\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙是慢性胆囊炎的超声表现，多与胆囊结石、胆汁淤积、饮食习惯有关。\",\"advice\":\"建议低脂饮食，规律三餐，避免暴饮暴食；进一步检查消化系统，必要时消化内科就诊。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大，回声均匀\",\"referenceValue\":\"脾脏大小正常，回声均匀\",\"unit\":\"-\",\"interpret\":\"脾脏轻度增大可见于感染、肝病、血液系统疾病等，需进一步明确原因。\",\"advice\":\"建议复查血常规、肝功能、肝炎病毒标志物，必要时血液科检查，定期随诊。\"},{\"conclusion\":\"右肾小囊肿\",\"examinationItem\":\"肾脏B超\",\"result\":\"右肾下极见大小约5mm无回声区，考虑小囊肿\",\"referenceValue\":\"无\",\"unit\":\"-\",\"interpret\":\"肾囊肿多为良性，小囊肿一般无症状，极少恶变，需定期观察。\",\"advice\":\"建议每年复查肾脏B超，监测囊肿大小变化；如出现腰痛、血尿等及时就医。\"},{\"conclusion\":\"前列腺增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"形态正常，回声均匀\",\"unit\":\"-\",\"interpret\":\"前列腺增大常见于良性前列腺增生，但回声欠均匀需排除前列腺癌。\",\"advice\":\"建议抽血查前列腺特异性抗原（PSA），必要时前列腺穿刺或泌尿外科进一步诊治。\"}]', '{\"breathingSystem\":95,\"digestiveSystem\":70,\"endocrineSystem\":75,\"immuneSystem\":80,\"circulatorySystem\":62,\"urinarySystem\":75,\"motionSystem\":95,\"senseSystem\":60}', '1', '2026-10-08 20:35:58', NULL, NULL, NULL, 1, 1);
INSERT INTO `health_assessment_report` VALUES (2, 8, '2026-10-08 21:19:11', 'admin', NULL, NULL, NULL, NULL, '轻度受损', '轻度受损', '中度受损', '能力完好', '轻度失能', '轻度失能', '', NULL, NULL, NULL, NULL, '72.5', '风险', '体检报告中空腹血糖、总胆固醇、甘油三酯、尿酸、肌酐共5项化验指标处于临界高值，影像学提示脂肪肝可能、慢性胆囊炎可能、脾轻度增大、右肾小囊肿及前列腺增大，内科查体见心率偏快、偶发早搏及末梢循环不良，眼科、耳鼻喉科、口腔科亦有多项异常，合计异常或临界指标约25项；其余血常规、尿常规、肿瘤标志物等多数指标正常。综合这些临床指标和数据分析：循环系统、消化系统（肝胆）、泌尿系统（肾、前列腺）及感官系统存在隐患，其中循环系统有“中危”风险；肝胆部位有“低危”风险；肾脏及前列腺有“低危”风险。建议进一步检查心脏、肝脏、脾脏、前列腺和肾功能，并加强生活管理。', '[{\"conclusion\":\"心率偏快\",\"examinationItem\":\"心率\",\"result\":\"92次/分\",\"referenceValue\":\"60-100次/分\",\"unit\":\"次/分\",\"interpret\":\"静息心率92次/分处于正常上限，老年人交感神经兴奋性增高或潜在心脏问题，结合偶发早搏及四肢末梢凉，提示循环系统需要关注。\",\"advice\":\"建议行动态心电图、心脏超声及血管功能评估，避免浓茶咖啡，定期监测血压和心率。\"},{\"conclusion\":\"偶发早搏\",\"examinationItem\":\"心律（内科查体）\",\"result\":\"偶发早搏\",\"referenceValue\":\"窦性，无早搏\",\"unit\":\"-\",\"interpret\":\"偶发早搏可见于正常人，也可由心肌缺血、电解质紊乱、甲亢等引起，需进一步评估其性质及频率。\",\"advice\":\"建议进行24小时动态心电图、电解质和甲状腺功能检查，避免熬夜、饮酒和过度劳累。\"},{\"conclusion\":\"皮肤弹性差、四肢末梢凉\",\"examinationItem\":\"内科查体（其他）\",\"result\":\"皮肤弹性差，四肢末梢凉\",\"referenceValue\":\"皮肤弹性好，四肢温暖\",\"unit\":\"-\",\"interpret\":\"提示末梢循环不良或血管功能减退，常见于动脉硬化、心输出量下降、甲状腺功能减退等。\",\"advice\":\"建议血管超声、踝肱指数、血脂血糖及甲状腺功能检查，注意保暖，戒烟限酒，适度有氧运动。\"},{\"conclusion\":\"老年性眼袋\",\"examinationItem\":\"眼睑\",\"result\":\"老年性眼袋，未见炎症\",\"referenceValue\":\"正常（无眼袋）\",\"unit\":\"-\",\"interpret\":\"老年性眼袋是眶隔松弛、脂肪膨出所致，一般不影响健康，但可能影响视野和外观。\",\"advice\":\"定期眼科检查，注意眼部护理；若眼袋明显影响生活，可咨询整形科。\"},{\"conclusion\":\"角膜老年环\",\"examinationItem\":\"角膜\",\"result\":\"轻度老年环\",\"referenceValue\":\"无\",\"unit\":\"-\",\"interpret\":\"角膜老年环是脂质在角膜周边沉积的表现，部分研究认为与血脂异常、动脉粥样硬化有关。\",\"advice\":\"建议检查血脂和颈动脉粥样硬化情况，低脂饮食，控制体重，必要时调脂治疗。\"},{\"conclusion\":\"结膜轻微充血\",\"examinationItem\":\"结膜\",\"result\":\"轻微充血\",\"referenceValue\":\"无充血\",\"unit\":\"-\",\"interpret\":\"结膜充血可由结膜炎、干眼症、用眼过度或环境刺激引起。\",\"advice\":\"注意用眼卫生，避免揉眼和长时间用眼，可滴用人工泪液；持续不退需眼科就诊。\"},{\"conclusion\":\"视力下降\",\"examinationItem\":\"视力\",\"result\":\"左0.3，右0.4\",\"referenceValue\":\"≥0.8（或1.0）\",\"unit\":\"-\",\"interpret\":\"视力下降符合老视特征，但也需排除白内障、青光眼、眼底病变等。\",\"advice\":\"建议到眼科验光配镜，定期检查眼底、眼压和裂隙灯，控制用眼时间。\"},{\"conclusion\":\"左耳听力轻度下降\",\"examinationItem\":\"听力\",\"result\":\"左耳轻度下降\",\"referenceValue\":\"听力正常\",\"unit\":\"-\",\"interpret\":\"老年性耳聋或中耳疾病所致，可能影响言语交流，并与社会隔绝有关。\",\"advice\":\"建议耳鼻喉科听力学检查，必要时佩戴助听器，避免噪声，控制血压血糖。\"},{\"conclusion\":\"鼻中隔轻度弯曲\",\"examinationItem\":\"鼻中隔\",\"result\":\"轻度弯曲\",\"referenceValue\":\"鼻中隔居中\",\"unit\":\"-\",\"interpret\":\"多为生理性弯曲，可引起鼻塞、鼻出血或引流不畅，一般无需处理。\",\"advice\":\"如无明显症状不需治疗；若出现反复鼻塞或头痛，可耳鼻喉科诊治。\"},{\"conclusion\":\"口咽部轻微充血\",\"examinationItem\":\"口咽部\",\"result\":\"轻微充血\",\"referenceValue\":\"黏膜淡红，无充血\",\"unit\":\"-\",\"interpret\":\"咽部炎症表现，与上呼吸道感染、烟酒刺激或慢性咽炎有关。\",\"advice\":\"多饮水，少食辛辣刺激食物，戒烟限酒，可用盐水漱口；症状明显时就医。\"},{\"conclusion\":\"口腔黏膜轻微炎症\",\"examinationItem\":\"口腔粘膜\",\"result\":\"轻微炎症\",\"referenceValue\":\"黏膜光滑红润，无炎症\",\"unit\":\"-\",\"interpret\":\"口腔黏膜炎症可由局部刺激、维生素缺乏、免疫力下降或口腔菌群失调引起。\",\"advice\":\"保持口腔清洁，均衡营养，补充B族维生素，避免过硬过热食物。\"},{\"conclusion\":\"唇部干燥脱屑\",\"examinationItem\":\"唇\",\"result\":\"干燥脱屑\",\"referenceValue\":\"唇部湿润红润\",\"unit\":\"-\",\"interpret\":\"与脱水、维生素缺乏、气候干燥或舔唇习惯有关。\",\"advice\":\"多喝水，使用润唇膏，避免舔唇，增加新鲜蔬果摄入。\"},{\"conclusion\":\"牙齿部分缺失，牙石较多\",\"examinationItem\":\"牙齿\",\"result\":\"部分缺失，余牙石较多\",\"referenceValue\":\"牙列完整，无牙石\",\"unit\":\"-\",\"interpret\":\"牙齿缺失影响咀嚼功能，牙石是牙周病的主要诱因，可加重牙龈退缩和牙槽骨吸收。\",\"advice\":\"及时口腔科洗牙、牙周治疗和修复缺失牙，早晚刷牙，使用牙线。\"},{\"conclusion\":\"牙周炎、牙龈退缩\",\"examinationItem\":\"牙周\",\"result\":\"牙周炎，牙龈退缩\",\"referenceValue\":\"牙周健康，无退缩\",\"unit\":\"-\",\"interpret\":\"牙周炎是老年人牙齿丧失的主要原因，与菌斑、糖尿病、吸烟有关，也增加心血管病风险。\",\"advice\":\"进行系统性牙周治疗（如龈上洁治、龈下刮治），控制血糖，戒烟，定期复查口腔。\"},{\"conclusion\":\"颞下颌关节轻微弹响\",\"examinationItem\":\"颞下颌关节\",\"result\":\"活动时轻微弹响\",\"referenceValue\":\"无弹响\",\"unit\":\"-\",\"interpret\":\"颞下颌关节功能紊乱的表现，与咀嚼习惯、牙齿缺失或关节盘移位有关。\",\"advice\":\"避免咀嚼硬物和大张口，进食软食，若伴疼痛或张口受限就诊口腔科。\"},{\"conclusion\":\"轻度脂肪肝可能\",\"examinationItem\":\"肝脏B超\",\"result\":\"实质回声略粗糙，考虑轻度脂肪肝可能\",\"referenceValue\":\"实质回声均匀，无脂肪浸润\",\"unit\":\"-\",\"interpret\":\"脂肪肝是由肝细胞内脂肪堆积过多所致，与高脂饮食、饮酒、肥胖、糖尿病、高血脂等有关，可发展为脂肪性肝炎、肝硬化。\",\"advice\":\"低脂低糖饮食，戒酒，规律有氧运动，控制体重，定期复查肝功和肝脏B超。\"},{\"conclusion\":\"慢性胆囊炎可能\",\"examinationItem\":\"胆囊B超\",\"result\":\"胆囊壁毛糙，考虑慢性胆囊炎可能\",\"referenceValue\":\"胆囊壁光滑，无增厚\",\"unit\":\"-\",\"interpret\":\"胆囊壁毛糙是慢性炎症的超声表现，可能因胆汁淤积、感染或结石刺激所致，常与不规律饮食、高脂饮食有关。\",\"advice\":\"规律进食、避免油腻，少吃高胆固醇食物；如有右上腹痛、恶心应及时就诊，定期复查B超。\"},{\"conclusion\":\"脾轻度增大\",\"examinationItem\":\"脾脏B超\",\"result\":\"轻度增大，回声均匀\",\"referenceValue\":\"脾脏大小正常\",\"unit\":\"-\",\"interpret\":\"脾大可由多种原因引起，如感染（病毒、寄生虫）、血液病、自身免疫病、淤血性肝病等，需明确病因。\",\"advice\":\"建议进一步查血常规、肝功能、病毒标志物（如EB病毒、巨细胞病毒）、自身免疫抗体，必要时血液科或感染科会诊。\"},{\"conclusion\":\"右肾小囊肿可能\",\"examinationItem\":\"肾脏B超\",\"result\":\"右肾下极见约5mm无回声区，考虑小囊肿可能\",\"referenceValue\":\"无囊肿\",\"unit\":\"-\",\"interpret\":\"单纯性肾囊肿是中老年人常见良性病变，一般无症状，不会影响肾功能，但需定期随访。\",\"advice\":\"每年复查肾脏B超，观察大小变化；如囊肿增大、疼痛、血尿或继发感染，需泌尿外科处理。\"},{\"conclusion\":\"前列腺形态增大\",\"examinationItem\":\"前列腺B超\",\"result\":\"形态略增大，回声欠均匀\",\"referenceValue\":\"前列腺大小正常，回声均匀\",\"unit\":\"-\",\"interpret\":\"前列腺增大常见于良性前列腺增生，回声欠均匀需警惕前列腺癌可能，结合PSA判断。\",\"advice\":\"抽血查前列腺特异性抗原（PSA），泌尿外科就诊评估，注意排尿症状，如尿频尿急尿不尽等。\"},{\"conclusion\":\"空腹血糖处于临界高值\",\"examinationItem\":\"空腹血糖\",\"result\":\"6.1\",\"referenceValue\":\"3.9-6.1\",\"unit\":\"mmol/L\",\"interpret\":\"空腹血糖6.1 mmol/L正好处于正常上限，属于糖尿病前期或空腹血糖受损的临界状态，若不干预易发展为糖尿病。\",\"advice\":\"控制精制碳水化合物和糖分摄入，增加运动，减轻体重，建议查糖化血红蛋白和餐后2小时血糖，定期复查。\"},{\"conclusion\":\"总胆固醇处于临界高值\",\"examinationItem\":\"总胆固醇\",\"result\":\"5.6\",\"referenceValue\":\"2.3-5.7\",\"unit\":\"mmol/L\",\"interpret\":\"总胆固醇5.6 mmol/L已接近上限，反映脂代谢轻度异常，是动脉粥样硬化和心脑血管疾病的危险因素。\",\"advice\":\"低脂饮食，减少动物内脏、油炸食品和蛋黄摄入，增加蔬果和全谷物，控制体重，必要时复查血脂。\"},{\"conclusion\":\"甘油三酯处于临界高值\",\"examinationItem\":\"甘油三酯\",\"result\":\"1.7\",\"referenceValue\":\"0.5-1.7\",\"unit\":\"mmol/L\",\"interpret\":\"甘油三酯1.7 mmol/L为正常上限，与高糖饮食、饮酒、肥胖和缺乏运动密切相关，过高可诱发胰腺炎。\",\"advice\":\"减少米饭面食等精制糖，戒酒，控制体重，规律有氧运动，定期复查。\"},{\"conclusion\":\"尿酸处于正常高值\",\"examinationItem\":\"尿酸\",\"result\":\"389\",\"referenceValue\":\"155-428\",\"unit\":\"umol/L\",\"interpret\":\"尿酸389 umol/L虽在正常范围内但接近上限，高尿酸血症与代谢综合征、高血压、肾病及痛风相关。\",\"advice\":\"低嘌呤饮食，少食动物内脏、海鲜、啤酒和浓肉汤，多饮水，每日至少2000ml，定期复查。\"},{\"conclusion\":\"肌酐处于正常高值\",\"examinationItem\":\"肌酐\",\"result\":\"128\",\"referenceValue\":\"53-136\",\"unit\":\"umol/L\",\"interpret\":\"肌酐128 umol/L在正常范围内偏高，可提示肾小球滤过功能轻度下降，也受肌肉量、年龄及蛋白摄入影响。\",\"advice\":\"避免滥用药物（如非甾体抗炎药），控制血压血糖，适量饮水，定期查肾功能和尿微量白蛋白。\"}]', '{\"breathingSystem\":85,\"digestiveSystem\":68,\"endocrineSystem\":78,\"immuneSystem\":65,\"circulatorySystem\":68,\"urinarySystem\":75,\"motionSystem\":90,\"senseSystem\":62}', '1', '2026-10-08 21:19:11', NULL, NULL, NULL, 1, 1);
INSERT INTO `knowledge_base` VALUES (6, '护理员工工作手册', 1, '手册', 1, 1, 'https://lining-qk.oss-cn-hangzhou.aliyuncs.com/2dac261f-29e6-423f-a8ac-f847c0255b63.pdf', '2026-10-07 22:31:33', '2026-10-07 22:31:33', NULL, NULL, '[\"b6a54b11-a474-4286-a4b6-ccfa0b7a9241\",\"9b023e6b-db8e-4017-a7a9-69b638d08be5\",\"9e0405c1-56fc-4805-8373-4667aa035341\",\"e199056b-3f73-4fd0-9f75-e4f9af472217\",\"c7003eb5-5303-435d-bdfc-197453661bfd\",\"c870e3bb-e635-4a1d-8948-39a177afd07b\",\"2780592d-5d5c-4c82-bc12-11672ea663d8\",\"5b4f8e69-9a14-4f66-a1e8-6e11ceb99dfa\",\"715fae47-d7a7-4e4a-b474-3e92bdc8ee82\",\"85e717c4-2e1a-4c79-9d73-a1bf2bb95961\",\"c851aaf4-b7bb-4d60-8f69-a167e79dd606\",\"afa85502-5551-4530-bde0-4f51d02cc244\",\"f74bd2f0-9b21-4afd-9936-f05ca4fb6c78\",\"4b37abeb-3e55-4013-9010-e13133bde70c\",\"dcb4a5ad-b0a4-4a71-89a4-d916e182174c\",\"b22fecde-51ed-4136-9b45-cbada9c1f364\",\"3774be6c-a40e-43d6-9837-d46da5e2d5c2\",\"b91254e9-f707-46fd-a30d-d90bccca3828\",\"9d4c0ef3-9f9a-41b3-82be-77a5b353d33f\",\"808bbd99-5967-4968-b5e1-f14cefdda4bd\",\"9d854d87-0c4e-4bc3-a5b7-fa3c402ca128\",\"11c5025f-a33a-4108-b7d6-566cf0332f15\",\"8661cb5c-68a1-4448-8d26-544e426771d3\",\"25ff55ee-ba82-4407-9181-d595b7a5e147\",\"71561e6d-77bb-4e9f-8538-e512c81ec8a5\",\"9d1d19b7-0180-48bd-b30c-e4f5bcc3e84f\",\"331a3593-ff82-40a8-a04d-e10d31744078\",\"d3d9f00a-0256-4941-b505-0116d7c6eb3f\",\"3e248a7a-51d8-4ad7-afb6-7ab32d2db6be\",\"1d1618d7-82f8-4c53-af4c-d77e5706b18d\",\"cac70a75-1706-4c76-96af-2bebbb7cfc14\",\"e80ee26a-95bc-40fc-ac49-f3c1ca3aade3\",\"e17c44d3-8a9b-485b-ab75-cfdbac27a3dd\",\"cf93b460-e81a-46fb-848c-62cba1846b05\",\"a7526c57-9360-4897-a765-755c7a41a281\",\"08aa8332-dd5f-4e99-97e2-712dd7e2efe7\",\"e2271980-8098-4eda-986d-2a9d1e704dbe\",\"fc14c56c-e9e6-4915-8b53-5f5f1af885a7\",\"43c2d94c-35d0-4fae-8cbb-ca72679d443a\"]');
INSERT INTO `knowledge_base` VALUES (7, '养老院-医疗基础知识', 1, '手册', 1, 1, 'https://lining-qk.oss-cn-hangzhou.aliyuncs.com/55efae6f-5696-488a-af96-e2173ff455b2.pdf', '2026-10-07 22:31:49', '2026-10-07 22:31:49', NULL, NULL, '[\"2bef1ddc-ebdf-4d8e-94bf-929a76db6d8e\",\"2b0152f3-3653-4826-8419-2ac995b4aaf8\",\"303e15cb-a50e-414a-a1fc-bdc7915a68a8\",\"a682b2e0-f793-476b-a4e6-330dfd3f1cec\",\"8e1f03ca-85f9-4147-abed-b464e296f65c\",\"4b2aca80-7da4-4c4b-9aaa-49e3d0ebdf58\",\"40599d2f-6a30-42af-b09b-492d3f2c1826\",\"42c9ef45-6488-4b90-a7f0-e85e29b2b7a3\",\"8486aff5-f2ec-47b8-b00a-a81796477d60\",\"3dd95d4d-f1e7-494c-8993-c63c8d67f79d\",\"9f7bcd63-b3e7-4521-a7f1-e7cf2d83130b\",\"228c8b35-bed3-4e2a-9430-f4ebdad151ff\",\"cd1d5139-4237-42c5-a1e6-fbad24ea80f2\",\"da5c0549-0ace-45b1-b354-b1eb189be866\",\"866b1d76-f926-402d-9b88-9cc6a66ca66a\",\"2ae20b06-7388-4766-b026-09a2019570c7\",\"f0722063-0abf-408f-ad80-ab354fe53e7f\",\"5f63d938-430d-4164-b3cc-ccb22e0fb8ec\",\"e2b10b7d-2449-485a-b735-8ac54a622e9a\",\"f18d0615-d4ae-4979-a4bd-c574b834d2f3\",\"4c707c31-3e8f-4661-9260-afc009e3d0b9\",\"f7f13ac1-889b-4396-836f-45d1b6ef8ad6\"]');
